function evidence = f90_xmech10_extract_reference_evidence( ...
        candidatePath, outDir)
%f90_xmech10_extract_reference_evidence Native reference replay.
%   This reference route preserves the source-authority current
%   simulation order: apply one scenario, explicitly update the linked
%   project model, then simulate it directly.  The current candidate route,
%   model, scenarios, and current score formula are not changed.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
subject = lower(strtrim(string(getenv( ...
    "SIMUVERITY_EVALUATION_SUBJECT"))));
assert(subject == "reference", "SimuVerity:F90:XMECH10:ReferenceSubject", ...
    "The native current replay is restricted to the sealed reference.");
expectedModelPresence = ...
    "present";
assert(isfile(candidatePath) && ...
    strcmpi(localFilePresence(candidatePath), expectedModelPresence), ...
    "SimuVerity:F90:XMECH10:ModelBinding", "Pinned root-model binding mismatch.");
[~, candidateName] = fileparts(candidatePath);
assert(string(candidateName) == "youBot_Arm", ...
    "SimuVerity:F90:XMECH10:ReferenceModelName", ...
    "The native current replay requires the bound youBot_Arm model.");

official = jsondecode(fileread(simuverity_official_scenarios_path()));
candidateRoot = string(fileparts(candidatePath));
sourceCandidates = [candidateRoot; fullfile(candidateRoot, "src")];
sourceMatches = arrayfun(@(root) ...
    isfile(fullfile(root, "YouBot_Arm.prj")), sourceCandidates);
assert(nnz(sourceMatches) == 1, "SimuVerity:F90:XMECH10:ProjectClosure", ...
    "The exact bundled youBot project was not found uniquely.");
sourceRoot = sourceCandidates(sourceMatches);
modelFile = candidatePath;
parameterFile = fullfile(sourceRoot, "Scripts_Data", "youBot_PARAM.m");
assert(strcmpi(localFilePresence(parameterFile), ...
    "present"), ...
    "SimuVerity:F90:XMECH10:ParameterBinding", ...
    "Pinned parameter-entry binding mismatch.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XMECH10:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(~isfolder(outDir), "SimuVerity:F90:XMECH10:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XMECH10:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(genpath(sourceRoot), "-begin");
oldDirectory = pwd;
directoryCleanup = onCleanup(@() cd(oldDirectory)); %#ok<NASGU>
cd(sourceRoot);

evidence = struct( ...
    "schema", "simuverity.f90-xmech10-evidence.v1", ...
    "task_id", "F90-XMECH-10", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "evidence_semantics", ...
        "complete resampled physical command, feedback, current, effort, payload and sensor traces; no score thresholds", ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "youBot_Arm";
try
    localEnsureProjectDependencies(sourceRoot);
    evalin("base", "youBot_PARAM");
    baseline = evalin("base", "YBT_Par");
    load_system(modelFile);
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;

    paths = localModelPaths(model);
    youBot_configureInput(model, "Control");
    youBot_configureMotors(model, "Motor");
    youBot_configureLoad(model, "Penalty");
    localInstallHarness(model, paths);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", localNumber(official.simulation.stop_s), ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout_youBot_Arm", ...
        "SimscapeLogType", "all", ...
        "SimscapeLogName", "simlog_youBot_Arm", ...
        "SimscapeLogLimitData", "off");

    localApplyScenario(baseline, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model, paths, sourceRoot);

    set_param(model, "StopTime", ...
        localNumber(official.simulation.smoke_stop_s));
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke
    set_param(model, "StopTime", ...
        localNumber(official.simulation.stop_s));

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(baseline, scenario);
            set_param(model, "SimulationCommand", "update");
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, official.simulation);
            rows(k) = localFinalizeScenario(rows(k), outputs, ...
                official.simulation);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
    fprintf(2, "%s\n", getReport(ME, "extended", ...
        "hyperlinks", "off"));
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XMECH10_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidencePath);
end

function paths = localModelPaths(model)
paths = struct( ...
    "input", model + "/Input", ...
    "arm", model + "/Arm", ...
    "scopes", model + "/Scopes", ...
    "actuation", model + "/Arm/Actuation", ...
    "motor_actuation", model + "/Arm/Actuation/Motor", ...
    "environment", model + "/Arm/Environment", ...
    "gripper_force", model + "/Arm/Environment/Gripper Force", ...
    "load", model + "/Arm/Environment/Load", ...
    "joint_position_mux", ...
        model + "/Scopes/Logging/Log Joint Angles/Mux2", ...
    "joint_effort_mux", ...
        model + "/Scopes/Logging/Log Torques/Mux2", ...
    "joint_constraint_mux", ...
        model + "/Scopes/Logging/Log Constraint Forces/Mux2", ...
    "motor_current_mux", model + "/Scopes/Mux1");
names = string(fieldnames(paths));
for name = names'
    assert(getSimulinkBlockHandle(paths.(name)) > 0, ...
        "SimuVerity:F90:XMECH10:RequiredPath", ...
        "Required model path is missing: %s", paths.(name));
end
end

function localInstallHarness(model, paths)
localBusTap(model, paths.input, 1, ...
    ["cP", "cB", "cF", "cW", "cG", "ca", "cb"], ...
    "F90 Command", "f90_joint_command_native");
localBusTap(model, paths.arm, 1, ...
    ["Belts.BeltIn.Box", "Belts.BeltIn.LC", ...
     "Belts.BeltOut.Box", "Belts.BeltOut.LC"], ...
    "F90 Sensor", "f90_sensor_state_native");
localBusTap(model, paths.input, 2, ...
    ["Belt In On", "Belt Out On"], ...
    "F90 Belt Command", "f90_belt_command_native");
localTapOutput(model, paths.joint_position_mux, ...
    "F90 Joint Position Tap", "f90_joint_position_native");
localTapOutput(model, paths.joint_effort_mux, ...
    "F90 Joint Effort Tap", "f90_joint_effort_native");
localTapOutput(model, paths.joint_constraint_mux, ...
    "F90 Joint Constraint Tap", "f90_joint_constraint_native");
localTapOutput(model, paths.motor_current_mux, ...
    "F90 Motor Current Tap", "f90_motor_current_native");
end

function localBusTap(parent, source, sourcePort, elements, prefix, variable)
selector = parent + "/" + prefix + " Selector";
mux = parent + "/" + prefix + " Mux";
tap = parent + "/" + prefix + " Tap";
add_block("simulink/Signal Routing/Bus Selector", selector, ...
    "OutputSignals", strjoin(elements, ","), ...
    "Position", [700 300 705 300 + 18 * numel(elements)]);
add_block("simulink/Signal Routing/Mux", mux, ...
    "Inputs", string(numel(elements)), ...
    "Position", [750 300 755 300 + 18 * numel(elements)]);
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries", ...
    "Position", [800 320 900 350]);
sourcePorts = get_param(source, "PortHandles");
selectorPorts = get_param(selector, "PortHandles");
muxPorts = get_param(mux, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
add_line(parent, sourcePorts.Outport(sourcePort), ...
    selectorPorts.Inport(1), "autorouting", "on");
for k = 1:numel(elements)
    conversion = parent + "/" + prefix + " Cast " + string(k);
    add_block("simulink/Signal Attributes/Data Type Conversion", ...
        conversion, "OutDataTypeStr", "double", ...
        "Position", [720 290 + 24 * k 745 305 + 24 * k]);
    conversionPorts = get_param(conversion, "PortHandles");
    add_line(parent, selectorPorts.Outport(k), ...
        conversionPorts.Inport(1), "autorouting", "on");
    add_line(parent, conversionPorts.Outport(1), ...
        muxPorts.Inport(k), "autorouting", "on");
end
add_line(parent, muxPorts.Outport(1), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localTapOutput(~, source, tapName, variable)
% Keep the non-invasive tap in the same subsystem as its source.  Simulink
% does not permit add_line to connect a deeply nested source port directly
% to a sink placed at the root model level.
parent = string(get_param(source, "Parent"));
tap = parent + "/" + tapName;
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries", ...
    "Position", [800 400 900 430]);
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
add_line(parent, sourcePorts.Outport(1), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(baseline, scenario)
parameters = baseline;
parameters.Battery.v = double(scenario.SupplyVoltage_V);
parameters.Payload.max_m = double(scenario.PayloadMass_kg);
parameters.Payload.Sph.rho = parameters.Payload.max_m / ...
    (4 / 3 * pi * parameters.Payload.Sph.rad^3);
parameters.Payload.Cube.rho = parameters.Payload.max_m / ...
    parameters.Payload.Cube.d^3;
    delayScale = double(scenario.SequenceDelayScale);
    parameters.Control.Logic.Delay_Move_Box = ...
        baseline.Control.Logic.Delay_Move_Box * delayScale;
    parameters.Control.Logic.Delay_Grip_Box = ...
        baseline.Control.Logic.Delay_Grip_Box * delayScale;
    parameters.Control.Logic.Delay_Drop_Box = ...
        baseline.Control.Logic.Delay_Drop_Box * delayScale;
    parameters.Control.Logic.Delay_Close_Grip = ...
        baseline.Control.Logic.Delay_Close_Grip * delayScale;
    parameters.Control.Logic.Delay_Belt_Clear = ...
        baseline.Control.Logic.Delay_Belt_Clear * delayScale;
    parameters.Control.Logic.Delay_Ship_Box = ...
        baseline.Control.Logic.Delay_Ship_Box * delayScale;
    parameters.BeltIn.Control.Delay_on = ...
        baseline.BeltIn.Control.Delay_on * delayScale;
    parameters.BeltOut.Control.Delay_on = ...
        baseline.BeltOut.Control.Delay_on * delayScale;
axes = ["Pivot", "Bicep", "Forearm", "Wrist", ...
    "Gripper", "Finger_A", "Finger_B"];
for axis = axes
    parameters.(axis).Motor.friction = ...
        baseline.(axis).Motor.friction * ...
        double(scenario.JointFrictionScale);
end
assignin("base", "YBT_Par", parameters);
    for name = ["SupplyVoltage_V", "PayloadMass_kg", ...
        "JointFrictionScale", "SequenceDelayScale"]
    assignin("base", name, double(scenario.(name)));
end
end

function localValidateSmoke(simOut)
for name = ["f90_joint_command_native", ...
        "f90_joint_position_native", ...
        "f90_motor_current_native", ...
        "f90_joint_effort_native", ...
        "f90_sensor_state_native", ...
        "f90_belt_command_native"]
    value = localGetOutput(simOut, name);
    assert(isa(value, "timeseries") && numel(value.Time) >= 1, ...
        "SimuVerity:F90:XMECH10:SmokeOutput", ...
        "Smoke run did not produce %s.", name);
end
simlog = localGetOutput(simOut, "simlog_youBot_Arm");
assert(~isempty(simlog), "SimuVerity:F90:XMECH10:SmokeSimlog", ...
    "Smoke run did not produce the native Simscape log.");
localPayloadSeries(simlog, "Px", "p", "m");
end

function outputs = localExtractOutputs(simOut, simulation)
time = (double(simulation.start_s): ...
    double(simulation.evidence_sample_s): ...
    double(simulation.stop_s))';
command = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_joint_command_native"), time);
assert(size(command, 2) == 7, "SimuVerity:F90:XMECH10:CommandWidth", ...
    "Joint command tap must have seven channels.");
command(:, 1:5) = command(:, 1:5) * pi / 180;
jointPosition = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_joint_position_native"), time);
motorCurrent = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_motor_current_native"), time);
jointEffort = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_joint_effort_native"), time);
jointConstraint = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_joint_constraint_native"), time);
sensor = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_sensor_state_native"), time);
beltCommand = localInterpMatrix(localWorkspaceSeries(simOut, ...
    "f90_belt_command_native"), time);
widths = [size(jointPosition, 2), size(motorCurrent, 2), ...
    size(jointEffort, 2), size(jointConstraint, 2), ...
    size(sensor, 2), size(beltCommand, 2)];
assert(isequal(widths, [7 7 7 21 4 2]), ...
    "SimuVerity:F90:XMECH10:OutputWidths", ...
    "Unexpected native output widths: %s", mat2str(widths));

simlog = localGetOutput(simOut, "simlog_youBot_Arm");
assert(~isempty(simlog), "SimuVerity:F90:XMECH10:Simlog", ...
    "The native Simscape log is missing.");
payload = [ ...
    localInterp(localPayloadSeries(simlog, "Px", "p", "m"), time), ...
    localInterp(localPayloadSeries(simlog, "Py", "p", "m"), time), ...
    localInterp(localPayloadSeries(simlog, "Pz", "p", "m"), time), ...
    localInterp(localPayloadSeries(simlog, "Px", "v", "m/s"), time), ...
    localInterp(localPayloadSeries(simlog, "Py", "v", "m/s"), time), ...
    localInterp(localPayloadSeries(simlog, "Pz", "v", "m/s"), time)];

outputs = struct( ...
    "time_s", time, ...
    "joint_command", command, ...
    "joint_position", jointPosition, ...
    "motor_current", motorCurrent, ...
    "joint_effort", jointEffort, ...
    "joint_constraint", jointConstraint, ...
    "payload_state", payload, ...
    "sensor_state", sensor, ...
    "belt_command", beltCommand);
end

function series = localPayloadSeries(simlog, axis, quantity, unit)
try
    node = simlog.Arm.Environment.Load.Box. ...
        Init_Box_6_DOF_Joint.(char(axis)).(char(quantity)).series;
    timeVector = node.time;
    valueVector = node.values(char(unit));
    series = struct( ...
        "time", double(timeVector(:)), ...
        "values", squeeze(double(valueVector)));
catch ME
    error("SimuVerity:F90:XMECH10:PayloadSeries", ...
        "Required physical payload series %s.%s is missing: %s", ...
        axis, quantity, ME.message);
end
end

function series = localWorkspaceSeries(simOut, name)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XMECH10:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
raw = double(value.Data);
sampleCount = numel(value.Time);
dimensions = size(raw);
if sampleCount == 1
    data = reshape(raw, 1, []);
else
    timeDimension = [];
    if dimensions(1) == sampleCount
        timeDimension = 1;
    elseif dimensions(end) == sampleCount
        timeDimension = numel(dimensions);
    else
        matches = find(dimensions == sampleCount, 1, "first");
        if ~isempty(matches), timeDimension = matches; end
    end
    assert(~isempty(timeDimension), "SimuVerity:F90:XMECH10:WorkspaceShape", ...
        "Tap %s has no dimension matching its %d timestamps.", ...
        name, sampleCount);
    order = [timeDimension, setdiff(1:numel(dimensions), ...
        timeDimension, "stable")];
    data = reshape(permute(raw, order), sampleCount, []);
end
series = struct("time", double(value.Time(:)), "values", data);
end

function values = localInterp(series, time)
values = localInterpMatrix(series, time);
assert(size(values, 2) == 1, "SimuVerity:F90:XMECH10:ScalarSeries", ...
    "A required scalar series has %d channels.", size(values, 2));
values = values(:, 1);
end

function values = localInterpMatrix(series, time)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XMECH10:EmptySeries", "Required series is empty.");
sourceTime = double(series.time(:));
sourceValues = double(series.values);
if isvector(sourceValues), sourceValues = sourceValues(:); end
[sourceTime, uniqueIndex] = unique(sourceTime, "stable");
sourceValues = sourceValues(uniqueIndex, :);
if numel(sourceTime) == 1
    values = repmat(sourceValues(1, :), numel(time), 1);
else
    values = interp1(sourceTime, sourceValues, time, ...
        "linear", "extrap");
end
values = double(values);
end

function row = localFinalizeScenario(row, outputs, simulation)
allValues = [outputs.time_s; outputs.joint_command(:); ...
    outputs.joint_position(:); outputs.motor_current(:); ...
    outputs.joint_effort(:); outputs.joint_constraint(:); ...
    outputs.payload_state(:); outputs.sensor_state(:); ...
    outputs.belt_command(:)];
expectedSamples = round((double(simulation.stop_s) - ...
    double(simulation.start_s)) / ...
    double(simulation.evidence_sample_s)) + 1;
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) == expectedSamples && ...
    outputs.time_s(1) == double(simulation.start_s) && ...
    outputs.time_s(end) >= double(simulation.stop_s);
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model, paths, sourceRoot)
motorVariants = find_system(paths.motor_actuation, ...
    "MatchFilter", @Simulink.match.allVariants, ...
    "LookUnderMasks", "all", "FollowLinks", "on", ...
    "Variant", "on");
motorChoices = strings(size(motorVariants));
for k = 1:numel(motorVariants)
    motorChoices(k) = string(get_param(motorVariants{k}, ...
        "OverrideUsingVariant"));
end
motorReferences = find_system(paths.motor_actuation, ...
    "MatchFilter", @Simulink.match.allVariants, ...
    "LookUnderMasks", "all", "FollowLinks", "on", ...
    "ReferenceBlock", "Motor_Lib/Motor");
dcSource = find_system(paths.motor_actuation, ...
    "MatchFilter", @Simulink.match.allVariants, ...
    "LookUnderMasks", "all", "FollowLinks", "on", ...
    "Name", "DC Source");
audit = struct( ...
    "control_input_variant", ...
        localVariantIs(paths.input, "Control"), ...
    "outer_motor_actuation_variant", ...
        localVariantIs(paths.actuation, "Motor"), ...
    "five_high_fidelity_arm_motor_variants", ...
        numel(motorVariants) == 5 && all(motorChoices == "Motor"), ...
    "five_arm_motor_library_references", numel(motorReferences) == 5, ...
    "two_commanded_measured_finger_axes_with_electrical_load", ...
        localFingerAxesAudit(paths.motor_actuation), ...
    "shared_physical_dc_supply", numel(dcSource) == 1, ...
    "motor_library_contains_hbridge_dc_motor_gear_and_feedback", ...
        localMotorLibraryAudit(fullfile(sourceRoot, ...
        "Libraries", "Motor_Lib.slx")), ...
    "penalty_gripper_contact_variant", ...
        localVariantIs(paths.gripper_force, "Penalty"), ...
    "free_payload_box_variant", localVariantIs(paths.load, "Box"), ...
    "command_to_arm_path", ...
        localPortConnects(paths.input, 1, paths.arm, 1), ...
    "belt_command_to_arm_path", ...
        localPortConnects(paths.input, 2, paths.arm, 2), ...
    "measured_state_feedback_to_sequence", ...
        localPortConnects(paths.arm, 1, paths.input, 1), ...
    "native_complete_physical_measurements", ...
        localAllBlocks( ...
        [paths.joint_position_mux, paths.joint_effort_mux, ...
         paths.joint_constraint_mux, paths.motor_current_mux]));
values = struct2cell(audit);
audit.core_path_qualified = all(cellfun(@(value) logical(value), values));
end

function pass = localMotorLibraryAudit(path)
pass = false;
try
    assert(isfile(path));
    % SLX is compressed, so validate the pinned library through a temporary
    % load and its real expanded block references instead of name matching
    % in the benchmark submission.
    load_system(path);
    hbridge = find_system("Motor_Lib/Motor", ...
        "LookUnderMasks", "all", "FollowLinks", "on", ...
        "Name", "H-Bridge");
    dcMotor = find_system("Motor_Lib/Motor", ...
        "LookUnderMasks", "all", "FollowLinks", "on", ...
        "Name", "Motor");
    gear = find_system("Motor_Lib/Motor", ...
        "LookUnderMasks", "all", "FollowLinks", "on", ...
        "Name", "Gear");
    feedback = find_system("Motor_Lib/Motor", ...
        "LookUnderMasks", "all", "FollowLinks", "on", ...
        "Name", "Subtract");
    pass = ~isempty(hbridge) && ~isempty(dcMotor) && ...
        ~isempty(gear) && ~isempty(feedback);
catch
end
end

function pass = localFingerAxesAudit(motorActuation)
pass = false;
try
    fingers = ["Finger A", "Finger B"];
    joints = ["PrismaticFingerA", "PrismaticFingerB"];
    qualified = false(size(fingers));
    for k = 1:numel(fingers)
        root = motorActuation + "/" + fingers(k);
        currentSource = find_system(root, "SearchDepth", 1, ...
            "Regexp", "on", "Name", "Current[\s\S]*Source");
        motorConstant = find_system(root, "LookUnderMasks", "all", ...
            "FollowLinks", "on", "Name", "PS Motor Const");
        resistance = find_system(root, "LookUnderMasks", "all", ...
            "FollowLinks", "on", "Name", "Resistor");
        frictionExpression = string(get_param( ...
            root + "/" + joints(k), "DampingCoefficient"));
        qualified(k) = ~isempty(currentSource) && ...
            ~isempty(motorConstant) && ~isempty(resistance) && ...
            contains(frictionExpression, "Motor.friction");
    end
    pass = all(qualified);
catch
end
end

function pass = localAllBlocks(paths)
pass = true;
for path = paths
    pass = pass && getSimulinkBlockHandle(path) > 0;
end
end

function pass = localVariantIs(path, expected)
pass = false;
try
    choice = string(get_param(path, "OverrideUsingVariant"));
    if strlength(choice) == 0
        choice = string(get_param(path, "LabelModeActiveChoice"));
    end
    pass = choice == expected;
catch
end
end

function pass = localPortConnects(source, outIndex, destination, inIndex)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(outIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function output = localGetOutput(simOut, name)
output = [];
try, output = simOut.get(name); catch, end
if isempty(output)
    try, output = evalin("base", name); catch, end
end
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
try
    if bdIsLoaded("Motor_Lib"), close_system("Motor_Lib", 0); end
catch
end
end

function localEnsureProjectDependencies(sourceRoot)
% The official project startup builds the Simscape language library from
% its checked-in +MyMath source.  Reproduce only that required build step;
% this is project initialization, not a reference-model modification.
libraryRoot = fullfile(sourceRoot, "Libraries");
generatedLibrary = fullfile(libraryRoot, "MyMath_lib.slx");
if ~isfile(generatedLibrary)
    oldDirectory = pwd;
    cleanup = onCleanup(@() cd(oldDirectory)); %#ok<NASGU>
    cd(libraryRoot);
    ssc_build MyMath;
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message), "causes", struct([]));
if ~isempty(ME.cause)
    causes = repmat(struct("identifier", "", "message", ""), ...
        numel(ME.cause), 1);
    for k = 1:numel(ME.cause)
        causes(k).identifier = string(ME.cause{k}.identifier);
        causes(k).message = string(ME.cause{k}.message);
    end
    info.causes = causes;
end
end

function value = localNumber(value)
value = sprintf("%.17g", double(value));
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XMECH10:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value, PrettyPrint=true), "UTF-8");
fwrite(fid, bytes, "uint8");
end

function root = localRepoRoot
root = fileparts(fileparts(fileparts(fileparts( ...
    fileparts(mfilename("fullpath"))))));
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
